// Basic sanity: library should report a non-zero, positive encoded version
FUZZ_ASSERT(ver > 0, "cmsGetEncodedCMMversion returned non-positive");
// Validation: Ensures function returns a sensible version code.

// Generate two random NUL-terminated strings and compare case-insensitively
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
// Requirement: both pointers must be valid C strings
int cmp = cmsstrcasecmp(s1.c_str(), s2.c_str());
(void)cmp; // result may be <,=,> 0; no further constraints
// Validation: Provides valid C strings and exercises comparison path.

// Open a fuzz-generated file and query its length
const char* path = FUZZ_PARAM_FILENAME();
FILE* f = fopen(path, "rb");
if (!f) { FUZZ_BAIL(); }
long int len = cmsfilelength(f);
(void)len;
fclose(f);
// Validation: Supplies a valid FILE* and closes it after use.

// Register plugins on the global context; pass NULL to reset/no-op safely
cmsBool ok = cmsPlugin(NULL);
(void)ok; // Either TRUE/FALSE is acceptable per implementation
// Validation: Safe registration path using NULL plugin avoids invalid pointers.

// Unregister all plugins from the global context
cmsUnregisterPlugins();
// Validation: Global cleanup path; no objects owned by stub.

// Set a process-wide error handler; use NULL to clear handler safely
cmsSetLogErrorHandler(NULL);
// Validation: Avoids unsafe function pointers by using NULL (allowed).

// Retrieve D50 white point in XYZ
const cmsCIEXYZ* d50 = cmsD50_XYZ();
FUZZ_ASSERT(d50 != NULL, "cmsD50_XYZ returned NULL");
// Validation: Asserts non-NULL static pointer.

// Retrieve D50 white point in xyY
const cmsCIExyY* d50 = cmsD50_xyY();
FUZZ_ASSERT(d50 != NULL, "cmsD50_xyY returned NULL");
// Validation: Asserts non-NULL static pointer.

// Convert random XYZ (non-negative) to xyY
cmsCIEXYZ src;
src.X = fabs(*FUZZ_PARAM(cmsFloat64Number));
src.Y = fabs(*FUZZ_PARAM(cmsFloat64Number));
src.Z = fabs(*FUZZ_PARAM(cmsFloat64Number));
// Avoid the degenerate all-zero vector by forcing some Y
if (src.X == 0.0 && src.Y == 0.0 && src.Z == 0.0) { src.Y = 1.0; }
cmsCIExyY dst;
cmsXYZ2xyY(&dst, &src);
// Validation: Provides valid pointers and guards against trivial zero XYZ.

// Convert random xyY to XYZ; constrain x,y to [0,1], Y to non-negative
cmsCIExyY src;
src.x = fmod(fabs(*FUZZ_PARAM(cmsFloat64Number)), 1.0);
src.y = fmod(fabs(*FUZZ_PARAM(cmsFloat64Number)), 1.0);
src.Y = fabs(*FUZZ_PARAM(cmsFloat64Number));
// y must not be zero to avoid division by zero inside typical converters
if (src.y == 0.0) { src.y = 1e-6; }
cmsCIEXYZ dst;
cmsxyY2XYZ(&dst, &src);
// Validation: Enforces domain constraints for stable conversion.

// Convert XYZ to Lab using D50 white point
const cmsCIEXYZ* wp = cmsD50_XYZ();
FUZZ_ASSERT(wp != NULL, "D50 XYZ whitepoint is NULL");
cmsCIEXYZ xyz;
xyz.X = fabs(*FUZZ_PARAM(cmsFloat64Number));
xyz.Y = fabs(*FUZZ_PARAM(cmsFloat64Number));
xyz.Z = fabs(*FUZZ_PARAM(cmsFloat64Number));
cmsCIELab lab;
cmsXYZ2Lab(wp, &lab, &xyz);
// Validation: Supplies valid pointers and a proper white point.

// Convert Lab to XYZ using D50 white point; constrain Lab to typical ranges
const cmsCIEXYZ* wp = cmsD50_XYZ();
FUZZ_ASSERT(wp != NULL, "D50 XYZ whitepoint is NULL");
cmsCIELab lab;
lab.L = fmod(fabs(*FUZZ_PARAM(cmsFloat64Number)), 110.0); // typical [0,100], allow small overrange
lab.a = fmod(*FUZZ_PARAM(cmsFloat64Number), 300.0) - 150.0; // roughly [-150,150]
lab.b = fmod(*FUZZ_PARAM(cmsFloat64Number), 300.0) - 150.0;
cmsCIEXYZ xyz;
