lab.b = fmod(*FUZZ_PARAM(cmsFloat64Number), 300.0) - 150.0;
cmsCIELCh lch;
cmsLab2LCh(&lch, &lab);
// Validation: Provides valid pointers and typical Lab ranges.

// Create a new context with optional user data; pass NULL plugin for safety
void* plugin = NULL; // avoid crafting arbitrary plugin chains
std::string user = FUZZ_PARAM_STR();
void* userData = (void*)user.c_str();
// Create the lcms context (opaque pointer type cmsContext)
cmsContext created = cmsCreateContext(plugin, userData);
if (!created) { FUZZ_BAIL(); }
// Allocate a holder for the cmsContext handle so the fuzzer runtime can manage a cmsContext * object
cmsContext* ContextID = (cmsContext*)_cmsMallocZero(NULL, (cmsUInt32Number)sizeof(cmsContext));
if (!ContextID) { cmsDeleteContext(created); FUZZ_BAIL(); }
*ContextID = created;
// Track liveness/state on the holder pointer (not the underlying opaque handle)
FUZZ_SET_ATTR_INT(ContextID, "alive", 1);
// Validation: Ensures non-NULL context creation, wraps the handle into a stable holder pointer for pooling.

// Destroy a previously created/duplicated context; ContextID is a holder to an opaque cmsContext handle
cmsContext ctx = *ContextID;
// Invoke the library to release the context
cmsDeleteContext(ctx);
// Free the holder memory allocated during creation/duplication
_cmsFree(NULL, ContextID);
// After this call the context must not be used; do not return it as output.
// Validation: Properly releases the context and its holder, avoiding leaks.

// Duplicate an existing context, with random user data; keep original alive
cmsContext orig = *ContextID;
std::string newUser = FUZZ_PARAM_STR();
void* newUserData = (void*)newUser.c_str();
cmsContext dup = cmsDupContext(orig, newUserData);
if (!dup) { FUZZ_BAIL(); }
// Wrap the duplicate in a holder so the fuzzer can manage it as cmsContext *
cmsContext* DupContextID = (cmsContext*)_cmsMallocZero(NULL, (cmsUInt32Number)sizeof(cmsContext));
if (!DupContextID) { cmsDeleteContext(dup); FUZZ_BAIL(); }
*DupContextID = dup;
FUZZ_SET_ATTR_INT(DupContextID, "alive", 1);
// Return both original holder (input) and the new duplicate holder
// Validation: Duplicates context and preserves ownership of both handles.

// Retrieve previously associated user data (may be NULL)
void* ud = cmsGetContextUserData(*ContextID);
// Store as an attribute pointer for potential later checks/use
FUZZ_SET_ATTR_PTR(ContextID, "user_data", ud);
(void)ud;
// Keep the context live by returning it as an output
// Validation: Non-intrusive access that doesn't modify ownership.

// Register plugins on a specific context; pass NULL plugin for a safe no-op
cmsBool ok = cmsPluginTHR(*ContextID, NULL);
(void)ok;
// Return the context as it remains valid
// Validation: Exercises per-context plugin registration safely.

// Unregister plugins from a specific context
cmsUnregisterPluginsTHR(*ContextID);
// Context remains valid; return it
// Validation: Per-context cleanup without altering ownership of the context.

// Set a per-context error handler; use NULL to clear safely
cmsSetLogErrorHandlerTHR(*ContextID, NULL);
// Return the context as it remains valid
// Validation: Safe handler configuration using NULL callback.

// Convert LCh to Lab; constrain LCh to reasonable ranges
cmsCIELCh lch;
lch.L = fmod(fabs(*FUZZ_PARAM(cmsFloat64Number)), 110.0); // L roughly [0,100]
