enc[1] = (cmsUInt16Number)(*FUZZ_PARAM(cmsUInt32Number) & 0xFFFF);
enc[2] = (cmsUInt16Number)(*FUZZ_PARAM(cmsUInt32Number) & 0xFFFF);
